"""Local editorial source inventory; deliberately separates discovery from publishing."""
import json
from collections import Counter
import news

def page():
 e=news.e
 def read(n):return json.loads((news.ROOT/'data'/n).read_text())
 media=read('regional-media-sources.json');cities=read('municipal-source-inventory.json');registry=read('feed-registry.json');families=read('source-families.json')
 inbox=read('inbox.json');articles=read('articles.json')
 rtv=[s for s in inbox if s.get('sourceId')=='rtv-utrecht' or 'rtv-utrecht' in s.get('sourceIds',[])]
 prepared={a.get('sourceUrl') for a in articles}
 def link(url,label):return '<a href="'+e(url)+'" target="_blank" rel="noopener">'+e(label)+'</a>'
 def media_row(s):
  feeds=''.join('<li>'+link(f['url'],'RSS / Atom')+' · '+e(f['status'])+(' · '+str(f['items'])+' items' if 'items' in f else '')+'</li>' for f in s.get('feedChecks',[])) or '<li>Geen feed bevestigd in deze controle. Website-index onderzoeken.</li>'
  return '<article class="source-entry"><h3>'+link(s['url'],s['name'])+'</h3><p>'+e(s['integration'])+'</p><ul>'+feeds+'</ul><p>'+e(s['next'])+'</p><small>'+link(s['evidence'],'Onderbouwing lokale dekking')+' · Technische controle '+e(s.get('checkedAt','')[:10])+'. Alleen signalering; geen artikel- of beeldlicentie.</small></article>'
 intro='''<section class="section source-map"><p class="eyebrow">PITO REDACTIE · 12 OKTOBER 2026</p><h1>Van bron naar lokaal nieuws</h1><p class="standfirst">Bronnen, ontbrekende koppelingen en de route naar publicatie — voor alle 26 gemeenten.</p><p>Een bereikbare RSS-feed is nog geen gepubliceerd artikel. Deze kaart maakt onderscheid tussen gevonden websites, geteste inname en redactionele verwerking. De lokale omroepenkaart is uitgebreid; volledige verdieping in verenigingen, ondernemers en woningprojecten is nog niet voor elke gemeente afgerond.</p><nav><a href="#gemeenten">Per gemeente</a> · <a href="#aanvoer">RSS en API’s</a> · <a href="#werkwijze">Verwerking</a> · <a href="/nieuws/redactie/gemeenten">Gedetailleerde bestaande bronkaart</a></nav>'''
 body='<h2>Waarom ontbreekt het RTV-voorbeeld?</h2><p>RTV Utrecht heeft al een RSS-koppeling. De registercontrole van 11 oktober registreerde 50 feeditems; dat is geen archief. In de huidige inbox staan '+str(len(rtv))+' RTV-signalen, waarvan '+str(sum(s.get('sourceUrl') in prepared for s in rtv))+' aan een artikelrecord gekoppeld zijn (ook concepten tellen mee). Het aangeleverde ongeval in Kanaleneiland ontbrak in de eerdere verzameling en is met de nieuwe RSS-run van 12 oktober wel in de inbox binnengekomen. Het is nog geen gepubliceerd PITO-artikel. De RSS-brondatum is 11 oktober 2026 om 19.42 uur, ná de vorige inname. De exacte artikelpagina kon niet via de webreader worden gelezen; de inhoud is nog niet bevestigd.</p><p>De huidige pipeline verzamelt signalen, maar publiceert niet zelfstandig. Website-archieven, lokale omroepen en de structurele redactionele verwerking zijn nog niet volledig aangesloten.</p>'
 adrows=[x for x in inbox if '://www.ad.nl/' in x.get('sourceUrl','')]
 ibrows=[x for x in inbox if '://indebuurt.nl/' in x.get('sourceUrl','')]
 report=read('source-coverage-refresh.json')
 fresh='<section class="source-refresh"><h2>Nieuwe broncontrole: 13 oktober 2026</h2><p>'+str(report['sitesChecked'])+' regionale websites in de eerdere inventaris; '+str(report['reachableFeeds'])+' RSS/Atom-feeds volgens eerdere controles bereikbaar. Dit is een opgeslagen inventaris, geen nieuwe livecontrole. Technische bereikbaarheid is geen volledige nieuwsdekking.</p>'+''.join('<p><strong>'+link(x['url'],x['name'])+'</strong> - '+e(x['method'])+'<br>'+e(x['action'])+'</p>' for x in report['primaryChannels'])+'<h3>RSS-dekking per gemeente</h3><div class="table-scroll"><table><tr><th>Gemeente</th><th>Feeds</th><th>Bronnen</th></tr>'+''.join('<tr><td>'+e(x['name'])+'</td><td>'+str(len(x['verifiedFeeds']))+'</td><td>'+(' / '.join(link(f['url'],f['name']) for f in x['verifiedFeeds']) or 'Geen regionale feed bevestigd')+'</td></tr>' for x in report['municipalities'])+'</table></div><p>AD, indebuurt, RTV Utrecht, NU.nl en lokale nieuwsplatforms zijn externe nieuwsbronnen, geen PITO-partners. We selecteren op concrete relevantie voor Utrecht, controleren de feiten waar mogelijk bij de oorspronkelijke organisatie en schrijven een eigen bericht met zichtbare bronlinks. Tekst- en fotorechten worden afzonderlijk vastgelegd. Een RSS-signaal is nog geen gepubliceerd artikel.</p></section>'
 body='<section><h2>Actuele dekkingsaudit · 13 oktober</h2><p>Bekijk de live brontests per gemeente, de actuele feedinname en waar verwerking nog stopt.</p><p><a href="/news-static/source-audit/gemeenten.html">Nieuwe live bronmatrix: alle 26 gemeenten</a> · <a href="/news-static/source-audit/index.html">Open het volledige bronnenonderzoek en download de actuele lijst</a> · <a href="/news-static/source-audit/verwerking.html">Verwerking per nieuwsbron en sportclubs</a> · <a href="/news-static/source-audit/volledige-verwerking.html">Afhandeling van iedere bronlink</a></p></section>'+fresh+body
 body+='<h2>AD en indebuurt aangesloten</h2><p>De gecontroleerde gemeentefeeds van AD en vier indebuurt-edities worden via de gewone inname verwerkt. Huidige voorraad: '+str(len(adrows))+' unieke AD-links en '+str(len(ibrows))+' indebuurt-links. Dit zijn signalen, geen overgenomen artikelen. Een gemeentefeed kan ook nieuws uit andere plaatsen bevatten.</p><p><a href="/nieuws/redactie/signalen?type=feeds&amp;q=www.ad.nl">Bekijk AD-signalen</a> · <a href="/nieuws/redactie/signalen?type=feeds&amp;q=indebuurt.nl">Bekijk indebuurt-signalen</a></p>'
 body+='<h2 id="aanvoer">Wat we uitlezen</h2><div class="table-scroll"><table><thead><tr><th>Bron</th><th>Inname</th><th>Historie / beperking</th><th>Laatste geregistreerde controle</th></tr></thead><tbody>'
 for s in registry:
  body+='<tr><td>'+link(s['endpoint'],s['name'])+'</td><td>'+e(s['adapter'])+' · '+e(s['state'])+'</td><td>'+e(s['history'])+'</td><td>'+e(s.get('latestCheck','')[:10])+'</td></tr>'
 body+='</tbody></table></div><p>“ok” of “tested” beschrijft een eerdere technische controle, geen permanente monitoring of publicatierecht. Intervallen in het register zijn voorstellen; er draait hiermee nog geen productieredactie.</p><h2>Bronnen naast nieuwsmedia</h2>'
 for s in families:body+='<details><summary>'+e(s['name'])+' · '+e(s['state'])+'</summary><p>'+e(s['purpose'])+'</p><p>'+e(s['next'])+'</p>'+link(s['url'],'Bron / documentatie')+'</details>'
 body+='''<details open><summary>112, Burgernet en AMBER Alert</summary><p>Combineer politiepersberichten, VRU-incidenten, regionale journalistiek en officiële opsporingsoproepen. De AMBER-adapter is geen volledige Burgernet-koppeling. Controleer de actuele technische voorwaarden van Burgernet voordat algemene acties worden overgenomen. P2000 is hooguit een aanvullend inzet-signaal; dekking en hergebruik zijn nog niet uitgewerkt.</p><p>Na beëindiging van een zoekactie onmiddellijk de actieve waarschuwing intrekken. Geen namen, foto's of signalementen onbeperkt bewaren. Geen slachtoffers of oorzaken afleiden uit een alarmering.</p><a href="https://www.burgernet.nl/static/Technische_koppelingen_Burgernet-AMBER_Alert_v0_8.pdf">Officiële technische documentatie AMBER (ouder document; actuele werking nog toetsen)</a></details>'''
 crawl_path=news.ROOT/'data/regional-archive-report.json'
 if crawl_path.exists():
  body+='<h2>Woerden · websitecrawl</h2><p>Indexlinks zijn onderzoekssignalen. Datums kunnen nog ontbreken; dit bewijst geen volledige driemaandsdekking.</p><ul>'
  for result in json.loads(crawl_path.read_text()):
   body+='<li><strong>'+e(result['name'])+'</strong>: '+str(result['pages'])+' pagina’s, '+str(result['discovered'])+' gevonden links · '+e(result['status'])+'. '+e(' · '.join(result.get('errors',[])))+(' Meer pagina’s beschikbaar.' if result.get('hasMore') else '')+(' Dynamische Meer laden-knop; aanvullende archiefinname nodig.' if result.get('dynamicPagination') else '')+'</li>'
  body+='</ul><p><a href="/nieuws/redactie/signalen?type=websites&amp;gemeente=woerden">Bekijk de gevonden Woerdense nieuwslinks</a></p>'
 body+='<h2 id="gemeenten">Lokale bronnen per gemeente</h2><p>Iedere gemeente gebruikt daarnaast RTV Utrecht, politie, VRU, officiële bekendmakingen en relevante verkeersbronnen. Hieronder staan aanvullende lokale media en de al gevonden lokale bronroutes. Het genoemde mediagebied is redactionele dekking, geen claim over een officiële zendvergunning.</p>'
 for m in cities:
  own=[s for s in media if m['municipality'] in s['municipalities']]
  topics=Counter(s['topic'] for s in m['sources'])
  body+='<details id="'+e(m['municipality'])+'"><summary>'+e(m['name'])+' · '+str(len(m['sources']))+' bestaande bronroutes</summary>'+''.join(media_row(s) for s in own)+'<p>Gevonden officiële / lokale routes: '+e(' · '.join(topics))+'</p><p><a href="/nieuws/redactie/gemeenten#'+e(m['municipality'])+'">Alle bronlinks, artikelen en hiaten voor '+e(m['name'])+'</a></p><p><strong>Nog per gemeente uitwerken:</strong> lokale uitgevers, woningcorporaties en projectwebsites; culturele locaties en organisatoren; sportclubs; ondernemersverenigingen; wijk- en dorpsorganisaties. Gevonden routes zijn nog niet allemaal inhoudelijk gelezen of gekoppeld.</p></details>'
 body+='''<h2 id="werkwijze">Zo maken we de aanvoer publiceerbaar</h2><ol><li><strong>Bron toelaten.</strong> Leg eigenaar, RSS/API of website-index, toegang, voorwaarden, gemeenten en bewaartermijn vast. RSS/API heeft voorkeur. Website-inname alleen na controle; geen blokkades of betaalmuren omzeilen.</li><li><strong>Nieuwe én historische links ophalen.</strong> RSS voor nieuwe signalen; toegestane sitemaps en gepagineerde archieven voor drie maanden historie. Bewaar paginacursor en voortgang per bron. Een lege feed betekent niet dat er geen nieuws is.</li><li><strong>Normaliseren en ontdubbelen.</strong> Bewaar bron-URL, brondatum, gebeurtenisdatum, controledatum, plaats en status apart. Groepeer meerdere berichten over hetzelfde incident; een wijziging is niet automatisch een nieuw artikel.</li><li><strong>Feiten controleren.</strong> Lees het brondocument, zoek primaire bevestiging waar mogelijk en onderscheid vastgestelde feiten van beweringen. Eén journalistieke bron kan alleen met duidelijke toeschrijving en passende redactionele beoordeling worden gebruikt. Niet alleen een titel herschrijven.</li><li><strong>Eigen artikel voorbereiden.</strong> Schrijf een eigen kop, intro en lopend nieuwsverhaal op basis van het gecontroleerde feitenoverzicht. Bewaar bronverwijzingen per feit. Tekst en foto's van anderen worden niet automatisch overgenomen.</li><li><strong>Selecteren en beoordelen.</strong> Beoordeel nabijheid, aantal getroffen inwoners, urgentie, praktische gevolgen, actualiteit en bronzekerheid. Veiligheid of politiek wint niet automatisch: impact en feitelijke relevantie bepalen de plek. Gevoelige incidenten, beschuldigingen en persoonsinformatie vragen redactionele controle.</li><li><strong>Strapi-concept → goedkeuring → website.</strong> Gebruik stabiele bron-ID’s voor updates in plaats van duplicaten. Alleen goedgekeurde artikelen publiceren. Een bronstoring mag nooit oude waarschuwingen als actueel presenteren.</li><li><strong>Bewaken.</strong> Meet per gemeente bronbereik, laatste geslaagde inname, wachtende signalen en publicaties. Signaleer ontbrekende bronnen, ongelezen documenten, dubbele verhalen en verlopen meldingen.</li></ol><h2>Concrete aansluitvolgorde</h2><ol><li>Zes aanvullende lokale feeds zijn aangesloten, samen met een nieuwe RTV-run goed voor 176 nieuwe signalen. Volgende stap: per bericht gemeente en feiten controleren, en een regelmatige inname activeren.</li><li>Politie + VRU + NDW: één incidentdossier, actualiteitscontrole en afloopstatus.</li><li>Alle gemeentelijke archieven, raadsbesluiten, omgevingsplannen en woningprojecten: inhoud lezen en gebeurtenissen van procedures onderscheiden.</li><li>PITO-agenda uit Strapi, sport, ondernemers en buurtverhalen: per gemeente aanvullende directe bronnen inventariseren.</li><li>Daarna pas geplande productieruns, monitoring en gecontroleerde Strapi-publicatie activeren.</li></ol><p><strong>Publicatiedoel:</strong> betrouwbare lokale dekking. Geen vaste artikelquota vullen met irrelevante meldingen of verzonnen inhoud.</p></section>'''
 css='<style>.source-map{max-width:1120px;margin:auto}.source-map h2{margin-top:36px}.source-map p,.source-map li{line-height:1.65}.source-map details{border-bottom:1px solid #ddd;padding:16px 0}.source-map summary{font-weight:700;cursor:pointer}.source-map a{color:#1050C2}.source-map .table-scroll{overflow-x:auto}.source-map table{border-collapse:collapse;width:100%;font-size:14px}.source-map td,.source-map th{padding:12px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top}.source-entry{padding:12px 0}.source-map li{margin-bottom:12px}.source-map small{color:#3F3F40}</style>'
 return news.layout('Bronnen en aanvoer per gemeente',css+intro+body,'/nieuws/redactie/bronnen')
